#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example() {
        assert_eq!(sliding_max(&[1, 3, -1, -3, 5, 3, 6, 7], 3), vec![3, 3, 5, 5, 6, 7]);
    }

    #[test]
    fn k_one_and_full() {
        assert_eq!(sliding_max(&[4, 2, 7], 1), vec![4, 2, 7]);
        assert_eq!(sliding_max(&[4, 2, 7], 3), vec![7]);
    }

    #[test]
    fn degenerate() {
        assert_eq!(sliding_max(&[1, 2], 0), Vec::<i32>::new());
        assert_eq!(sliding_max(&[1, 2], 3), Vec::<i32>::new());
        assert_eq!(sliding_max(&[], 1), Vec::<i32>::new());
    }

    #[test]
    fn decreasing_and_duplicates() {
        assert_eq!(sliding_max(&[9, 8, 7, 6, 5], 2), vec![9, 8, 7, 6]);
        assert_eq!(sliding_max(&[2, 2, 2, 2], 2), vec![2, 2, 2]);
    }

    #[test]
    fn large_input_is_fast() {
        let v: Vec<i32> = (0..200_000).map(|i| ((i * 7919) % 10007) as i32).collect();
        let r = sliding_max(&v, 1000);
        assert_eq!(r.len(), 200_000 - 1000 + 1);
        assert_eq!(r[0], *v[..1000].iter().max().unwrap());
        let last = &v[v.len() - 1000..];
        assert_eq!(*r.last().unwrap(), *last.iter().max().unwrap());
    }
}
